ALTER USER 'root'@'localhost' IDENTIFIED BY 'Test12345';
FLUSH PRIVILEGES;

USE customer_behavior;
SELECT * FROM customer_shopping_behavior LIMIT 10;

#Q1. What is the total revenue generated by male vs. female customers?
select gender, SUM(`purchase amount (usd)`) as revenue
from customer_shopping_behavior
group by gender;

#Q2. Which customers used a discount but still spent more than the average purchase amount?
select `customer id`, `purchase amount (usd)`
from customer_shopping_behavior
where `discount applied` = 'Yes' and `purchase amount (usd)` >= (select AVG(`purchase amount (usd)`) from customer_shopping_behavior);

#Q3. Which are the top 5 products with the highest average review rating.
select `item purchased`,
	ROUND(AVG(`review rating`), 2) as `Average Product Rating`
from customer_shopping_behavior
group by `item purchased`
order by AVG(`review rating`) desc
limit 5;

#Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
SELECT `shipping type`,
	ROUND(AVG(`purchase amount (USD)`),2)
from customer_shopping_behavior
where `shipping type` in ("Standard","Express")
group by `shipping type`;

#Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
SELECT `subscription status`,
COUNT(`customer id`) AS `total customers`,
ROUND(AVG(`purchase amount (USD)`),2) as `avg spend`,
ROUND(SUM(`purchase amount (USD)`),2) as `total revenue`
from customer_shopping_behavior
GROUP BY `subscription status`
ORDER BY `total revenue` DESC, `avg spend` DESC;

#Q6. Which 5 product have a highest percentage of purchase with discount applied?
SELECT `item purchased`,
ROUND(SUM(CASE WHEN `discount applied` = 'Yes' THEN 1 ELSE 0 END)/COUNT(*) * 100,2) AS `discount rate`
FROM customer_shopping_behavior
GROUP BY `item purchased`
ORDER BY `discount rate` desc
LIMIT 5;

#Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.
WITH `customer type` as (
SELECT `customer id`, `previous purchases`,
CASE
	WHEN `previous purchases` = 1 THEN 'New'
    WHEN `Previous purchases` BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS `customer segment`
FROM customer_shopping_behavior
)
SELECT `customer segment`, count(*) as 'Number of Customers'
FROM `customer type`
GROUP BY `customer segment`;

#Q8. What are the top 3 most purchased products within each category?
WITH item_counts AS (
	SELECT `category`,
		`item purchased`,
		COUNT(`customer id`) as `total orders`,
		ROW_NUMBER() OVER (
			partition by `category` 
			order by count(`customer id`) DESC
	) AS `item rank`
FROM customer_shopping_behavior
GROUP BY `category`, `item purchased`
)
SELECT `item rank`, `category`, `item purchased`, `total orders`
FROM item_counts
WHERE `item rank` <= 3;

#Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT `subscription status`,
COUNT(`customer id`) as `repeat buyers`
FROM customer_shopping_behavior
WHERE `previous purchases` > 5
GROUP BY `subscription status`;

#Q10. What is the revenue contribution of each age group?
SELECT `age`,
	SUM(`purchase amount (USD)`) as `total revenue`
FROM customer_shopping_behavior
GROUP BY `age`
ORDER BY `total revenue` DESC;















